FUNCTION_BLOCK FB_S11
VAR_INPUT
    SensorCurrent : REAL;
    FallbackValue : REAL;
END_VAR
VAR_OUTPUT
    SensorValid : BOOL := FALSE;
    DegradedMode : BOOL := FALSE;
    ControlValue : REAL := 0.0;
    AlarmLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    Initialized : BOOL := FALSE;
    FaultDetected : BOOL := FALSE;
    InRecoveryBand : BOOL := FALSE;
    InMeasurementBand : BOOL := FALSE;
    FaultTiming : BOOL := FALSE;
    RecoveryTiming : BOOL := FALSE;
    FaultTicks : UINT := UINT#0;
    RecoveryTicks : UINT := UINT#0;
    BlinkTicks : UINT := UINT#0;
END_VAR

(*
    每次调用代表20 ms；计数器按相邻调用之间的时间计时。
    断线起始拍计数为0，经过100个间隔后进入降级。
    恢复起始拍计数为0，保持降级于恢复拍偏移0..149，
    在偏移150处允许退出，符合C9的保持边界。

    待审冲突：
    C10要求上电当拍SensorValid=FALSE、ControlValue=0.0，
    与“4..20 mA时SensorValid=TRUE并立即换算”在上电输入
    有效时冲突。本实现保留明确初态，首次调用仅初始化，
    第二次调用开始检测；不能声称同时满足两种解释。

    待审未定义区间：
    原文没有指定滞回带内非降级ControlValue的数值。
    本实现仅在4..20 mA内更新测量值，其余非降级拍保持。
    SensorValid在断线阈值与恢复阈值之间保持原状态。
    非降级断线等待期间也保持ControlValue，符合C1公式；
    C1注释若被解释为禁止此阶段保持失效测量值，则需澄清。
    本源码未附带编译或逐周期验证结果。
*)

IF NOT Initialized THEN
    SensorValid := FALSE;
    DegradedMode := FALSE;
    ControlValue := 0.0;
    AlarmLamp := FALSE;
    Status := WORD#16#0000;

    FaultDetected := FALSE;
    InRecoveryBand := FALSE;
    InMeasurementBand := FALSE;
    FaultTiming := FALSE;
    RecoveryTiming := FALSE;
    FaultTicks := UINT#0;
    RecoveryTicks := UINT#0;
    BlinkTicks := UINT#0;
    Initialized := TRUE;
ELSE
    FaultDetected :=
        (SensorCurrent < 3.6) OR (SensorCurrent > 21.0);
    InRecoveryBand :=
        (SensorCurrent >= 3.8) AND (SensorCurrent <= 20.5);
    InMeasurementBand :=
        (SensorCurrent >= 4.0) AND (SensorCurrent <= 20.0);

    (* 故障优先；滞回中间带保持有效性状态。 *)
    IF FaultDetected THEN
        SensorValid := FALSE;
    ELSIF InRecoveryBand THEN
        SensorValid := TRUE;
    END_IF;

    (* 未恢复的断线状态持续计时；恢复立即清除断线计时。 *)
    IF NOT SensorValid THEN
        IF NOT FaultTiming THEN
            FaultTiming := TRUE;
            FaultTicks := UINT#0;
            BlinkTicks := UINT#0;
        ELSE
            IF FaultTicks < UINT#100 THEN
                FaultTicks := FaultTicks + UINT#1;
            END_IF;

            IF BlinkTicks >= UINT#49 THEN
                BlinkTicks := UINT#0;
            ELSE
                BlinkTicks := BlinkTicks + UINT#1;
            END_IF;
        END_IF;

        IF FaultTicks >= UINT#100 THEN
            DegradedMode := TRUE;
        END_IF;
    ELSE
        FaultTiming := FALSE;
        FaultTicks := UINT#0;
        BlinkTicks := UINT#0;
    END_IF;

    (* 必须连续处于恢复带；离开恢复带就重置确认计时。 *)
    IF DegradedMode THEN
        IF SensorValid AND InRecoveryBand THEN
            IF NOT RecoveryTiming THEN
                RecoveryTiming := TRUE;
                RecoveryTicks := UINT#0;
            ELSE
                IF RecoveryTicks < UINT#150 THEN
                    RecoveryTicks := RecoveryTicks + UINT#1;
                END_IF;
            END_IF;

            IF RecoveryTicks >= UINT#150 THEN
                DegradedMode := FALSE;
                RecoveryTiming := FALSE;
                RecoveryTicks := UINT#0;
            END_IF;
        ELSE
            RecoveryTiming := FALSE;
            RecoveryTicks := UINT#0;
        END_IF;
    ELSE
        RecoveryTiming := FALSE;
        RecoveryTicks := UINT#0;
    END_IF;

    (* 降级输出优先，备用输入每拍更新。 *)
    IF DegradedMode THEN
        ControlValue := FallbackValue;
    ELSIF SensorValid AND InMeasurementBand THEN
        ControlValue := ((SensorCurrent - 4.0) / 16.0) * 100.0;
    END_IF;

    IF DegradedMode THEN
        AlarmLamp := TRUE;
        IF SensorValid THEN
            Status := WORD#16#8A03;
        ELSE
            Status := WORD#16#8A02;
        END_IF;
    ELSIF NOT SensorValid THEN
        (* 25拍亮、25拍灭：周期1 s，频率1 Hz。 *)
        AlarmLamp := BlinkTicks < UINT#25;
        Status := WORD#16#8A01;
    ELSE
        AlarmLamp := FALSE;
        Status := WORD#16#0000;
    END_IF;
END_IF;
END_FUNCTION_BLOCK
